/**
 * Brand font loading for every generated image route (/api/og, /api/image/brief).
 *
 * Satori reads TTF/OTF/WOFF but not woff2, so these fetch the TTF copies
 * generated by scripts/generate-og-fonts.mjs (committed under
 * public/fonts/og/). The route runs on the edge runtime, where static assets
 * are only reachable over same-origin fetch — there is no filesystem.
 */

/**
 * Family names satori registers the faces under. Templates must reference these
 * exact strings: a family satori cannot resolve sends it to the dynamic Google
 * font loader for any glyph outside its default face, and that download failing
 * aborts the render mid-stream (a 200 with an empty body, not an error).
 */
export const OG_FONT_DISPLAY = "Archivo SemiCondensed";
export const OG_FONT_BODY = "Archivo";
/** The regime word's face, expanded like the site's stamp (.type-stamp). */
export const OG_FONT_STAMP = "Archivo Expanded";

/**
 * What the cards print in place of the site's symbols.
 *
 * Satori answers a glyph the faces lack by downloading a Google font for it, and
 * when that download fails it aborts the render *after* the response headers are
 * already sent -- the caller gets a 200 with an empty body, which is how the
 * decision card silently began downloading as a 0-byte PNG. The faces were
 * Fontsource's generic Latin subset then, without →, ≤ or ≥, and all three were
 * rewritten here; → printed as "->". Since 2026-10-07 the faces are subset to the
 * site's text (app/styles/fonts.css) and draw all three, so the arrow prints as
 * itself. The comparisons stay words by choice.
 */
const UNSUPPORTED_GLYPHS: ReadonlyArray<readonly [RegExp, string]> = [
  /* Words, not "≤": the cards travel to people who do not read code, and the
     sentences these come from ("Funding pressure ≤ 66") read naturally either way. */
  [/\s*\u2264\s*/g, " at or below "],
  [/\s*\u2265\s*/g, " at or above "],
];

/** Rewrites text so an image template can only emit glyphs the faces carry. */
export const toImageSafeText = (value: string): string =>
  UNSUPPORTED_GLYPHS.reduce((text, [pattern, replacement]) => text.replace(pattern, replacement), value);

/**
 * The same rewrite over every string field of a template's props. Applied where a
 * route hands props to a template, so a template added later cannot forget it —
 * the weekly card did, and printed "Funding pressure ▯ 66" on the most-shared image.
 */
export const toImageSafeProps = <T extends object>(props: T): T => {
  const safe = { ...props };
  for (const [key, value] of Object.entries(safe)) {
    if (typeof value === "string") Reflect.set(safe, key, toImageSafeText(value));
  }
  return safe;
};

type OgFont = {
  name: string;
  data: ArrayBuffer;
  weight: 400 | 600 | 700;
  style: "normal";
};

/* Static instances of the one variable file the site serves, written by
   scripts/generate-og-fonts.mjs: the call semi-condensed, text at normal
   width, the regime word expanded — the same three voices as the pages. */
const FACES: ReadonlyArray<{ path: string; name: string; weight: 400 | 600 | 700 }> = [
  { path: "/fonts/og/archivo-semicondensed-700.ttf", name: OG_FONT_DISPLAY, weight: 700 },
  { path: "/fonts/og/archivo-400.ttf", name: OG_FONT_BODY, weight: 400 },
  { path: "/fonts/og/archivo-600.ttf", name: OG_FONT_BODY, weight: 600 },
  { path: "/fonts/og/archivo-expanded-700.ttf", name: OG_FONT_STAMP, weight: 700 },
];

let cache: Promise<OgFont[] | undefined> | null = null;

/**
 * Resolves the brand faces for ImageResponse, or undefined when any face
 * fails to load — the caller then omits the fonts option so the card still
 * renders with satori's built-in fallback instead of erroring the unfurl.
 */
export const loadOgFonts = (requestUrl: string): Promise<OgFont[] | undefined> => {
  cache ??= Promise.all(
    FACES.map(async (face) => {
      const response = await fetch(new URL(face.path, requestUrl));
      if (!response.ok) {
        throw new Error(`OG font fetch failed: ${face.path} (${response.status})`);
      }
      return {
        name: face.name,
        data: await response.arrayBuffer(),
        weight: face.weight,
        style: "normal" as const,
      };
    }),
  ).catch(() => {
    cache = null; // Retry on the next request rather than caching the failure.
    return undefined;
  });
  return cache;
};
